try {
    var getInboundRec = new GlideRecord('incident');
    getInboundRec.get('ed92e8d173d023002728660c4cf6a7bc');

    var getPayload = JSON.parse(getInboundRec.description);

    var resources = getPayload.PAYLOAD.Resources;

    for (var r = 0; r < resources.length; r++) {
        var resource = resources[r];
        gs.info("----- Processing Resource " + (r + 1) + " (id: " + resource.id + ") -----");

        // Check if attributes exist
        if (resource.attributes && resource.attributes.meta && resource.attributes.values) {
            var metaArr = resource.attributes.meta;
            var valuesObj = resource.attributes.values;

            // Collect into a map like before
            var valueMap = {};
            for (var i = 0; i < metaArr.length; i++) {
                var keyName = metaArr[i].key;

                if (valuesObj[keyName] && valuesObj[keyName].length > 0) {
                    var val = valuesObj[keyName][0].value;
                    valueMap[keyName] = val;
                    gs.info("Resource " + (r + 1) + " | Key: " + keyName + " | Value: " + val);
                }
            }

            // Example variable assignment (only if you need)
            var accountNumber = valueMap.accountNumber;
            var cashValue = valueMap.cashValue;

            gs.info("Resource " + (r + 1) + " accountNumber: " + accountNumber);
            gs.info("Resource " + (r + 1) + " cashValue: " + cashValue);
        } else {
            gs.info("Resource " + (r + 1) + " has no attributes");
        }
    }

} catch (ex) {
    gs.info('Error From MSS Taskize Bubble Create/Update: ' + ex);
}
